// 全部旧行及真实绑定逐值保留；新增行须先取真实差分再由cache/history已经分配的结果绑定。
#include "visit_appointment_receipts.hpp"
#include "visit_appointment_detail.hpp"
#include "resident/kernel/command_types.hpp"
#include <set>
namespace hanmo::resident {namespace {
struct Source{StableId kind,command,actor;Integer tick=-1;const std::optional<VisitAppointmentPlayerReceipt>* binding=nullptr;bool authored=false;};
Source source(const VisitAppointmentState& state,const StableId& id){if(const auto* s=state.offered.find(id))return {visit_appointment_offered_kind,"offer_visit_appointment",s->contact.actor_id,s->contact.tick,&s->player_receipt,bool(s->authored_origin)};if(const auto* s=state.collected.find(id))return {visit_appointment_collected_kind,"collect_visit_appointment",s->contact.actor_id,s->contact.tick,&s->player_receipt};if(const auto* s=state.accepted.find(id))return {visit_appointment_accepted_kind,"accept_visit_appointment",s->actor_id,s->tick,&s->player_receipt};return {};}
bool command(const StableId& kind){return kind=="offer_visit_appointment"||kind=="collect_visit_appointment"||kind=="accept_visit_appointment";}
Status matches(const VisitAppointmentState& state,const StableId& id,const StableId& actor,const StableId& kind,Integer tick,const ReceiptDetails& details){const auto s=source(state,id);const auto* effect=std::get_if<InteractionEffect>(&details.data);if(!s.binding||s.authored||s.command!=kind||s.actor!=actor||s.tick!=tick||!effect||effect->settlement_result!=id||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return common_failure("VisitAppointmentActualSourceRequired",id);return common_success();}
template<class T>bool additions(const VisitAppointmentState& before,const VisitAppointmentState& after,const OrderedTable<T>& old,const OrderedTable<T>& now,std::vector<StableId>& ids){if(now.size()<old.size())return false;for(std::size_t n=0;n<old.size();++n){const auto& id=old.order()[n];const auto s=source(before,id);if(now.order()[n]!=id||!s.binding||(s.authored?bool(*s.binding):!bool(*s.binding)))return false;auto a=encode_visit_appointment_fact(before,id),b=encode_visit_appointment_fact(after,id);if(!a.ok||!b.ok||!compare_boundary(a.value,b.value).exact())return false;}for(std::size_t n=old.size();n<now.size();++n)ids.push_back(now.order()[n]);return true;}
Status bindings(const CommonStore& c,const VisitAppointmentState& state){using visit_appointment_detail::serial;Integer last_result=0,last_revision=0;std::set<StableId> results;std::map<StableId,Integer> requests;std::size_t count_rows=0;
 for(const auto& row:c.state().facts.rows()){if(row.second.domain!=visit_appointment_module)continue;++count_rows;const auto s=source(state,row.first);if(!s.binding)return common_failure("VisitAppointmentPermanentResultRequired",row.first);if(s.authored){if(*s.binding||row.second.id!=row.first||row.second.kind!=s.kind)return common_failure("VisitAppointmentAmbiguousProducer",row.first);continue;}if(!*s.binding)return common_failure("VisitAppointmentPermanentResultRequired",row.first);const auto& b=**s.binding;const auto fact=serial(row.first,s.kind,c.state().next_instance_id),result=serial(b.result_id,"result",c.state().next_instance_id);const auto* sequence=c.state().request_sequences.find(b.request_actor_id);if(row.second.id!=row.first||row.second.kind!=s.kind||!fact||!result||*fact<=last_result||*result<=*fact||*result<=last_result||b.result_revision<=last_revision||b.result_revision>c.revision()||b.request_actor_id!=s.actor||!sequence||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*sequence||requests[b.request_actor_id]>=b.request_sequence||!results.insert(b.result_id).second)return common_failure("InvalidVisitAppointmentPlayerBinding",row.first);last_result=*result;last_revision=b.result_revision;requests[b.request_actor_id]=b.request_sequence;
  const HistoryRecord* previous=nullptr;const HistoryRecord* lower=nullptr;std::size_t found=0;for(const auto& h:c.state().history){if(h.result_id==b.result_id){lower=previous;if(++found>1||h.actor_id!=b.request_actor_id||h.kind!=s.command||h.tick!=s.tick)return common_failure("VisitAppointmentHistoryMismatch",row.first);}previous=&h;}if(lower){auto bound=serial(lower->result_id,"result",c.state().next_instance_id);if(!bound||*bound>=*fact)return common_failure("VisitAppointmentAllocationMismatch",row.first);}const auto* cached=c.state().results.find(b.request_actor_id+":"+std::to_string(b.request_sequence));if(cached){if(found!=1||!*cached||!(*cached)->ok||(*cached)->result_id!=b.result_id||(*cached)->revision!=b.result_revision||!(*cached)->details)return common_failure("VisitAppointmentCacheMismatch",row.first);auto valid=matches(state,row.first,b.request_actor_id,(*cached)->kind,(*cached)->tick,*(*cached)->details);if(!valid.ok)return valid;}
 }
 if(count_rows!=state.offered.size()+state.collected.size()+state.accepted.size())return common_failure("VisitAppointmentBindingCoverageMismatch");return common_success();}
}
Outcome<StableId> visit_appointment_new_player_source(const VisitAppointmentState* before,const VisitAppointmentState* after,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick){auto fail=[]()->Outcome<StableId>{return {false,{},common_failure("VisitAppointmentNewPlayerSourceRequired").error};};if(!after){if(before||command(kind))return fail();return {true,{}, {}};}if(!before||(before->version!=1&&before->version!=2)||after->version!=before->version)return fail();std::vector<StableId> added;if(!additions(*before,*after,before->offered,after->offered,added)||!additions(*before,*after,before->collected,after->collected,added)||!additions(*before,*after,before->accepted,after->accepted,added))return fail();if(!command(kind)){if(added.empty())return {true,{}, {}};if(kind!="advance")return fail();for(const auto& id:added){const auto s=source(*after,id);if(!s.authored||!s.binding||*s.binding)return fail();}return {true,{}, {}};}if(added.size()!=1)return fail();const auto s=source(*after,added.front());if(!s.binding||*s.binding||s.authored)return fail();auto valid=matches(*after,added.front(),actor,kind,tick,details);return valid.ok?Outcome<StableId>{true,added.front(),{}}:Outcome<StableId>{false,{},valid.error};}
Status bind_visit_appointment_player_result(CommonStore& c,VisitAppointmentState& state,const StableId& id,const StableId& actor,Integer request,const CommitResult& result){if(id.empty())return command(result.kind)?common_failure("VisitAppointmentNewPlayerSourceRequired"):common_success();const auto s=source(state,id);const auto* cached=c.state().results.find(actor+":"+std::to_string(request));const auto* sequence=c.state().request_sequences.find(actor);const auto* head=c.state().facts.find(id);if(s.authored||!s.binding||*s.binding||!result.ok||!result.details||result.tick!=c.tick()||result.revision!=c.revision()||!cached||cached->get()!=&result||!sequence||*sequence!=request||c.state().history.empty()||!head||head->id!=id||head->kind!=s.kind||head->domain!=visit_appointment_module)return common_failure("VisitAppointmentActualResultRequired",id);const auto& h=c.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=result.kind||h.tick!=result.tick)return common_failure("VisitAppointmentActualHistoryRequired",id);auto valid=matches(state,id,actor,result.kind,result.tick,*result.details);if(!valid.ok)return valid;auto& b=*const_cast<std::optional<VisitAppointmentPlayerReceipt>*>(s.binding);b.emplace(S3PlayerReceiptBuildView{result.result_id,actor,request,result.revision});valid=bindings(c,state);if(!valid.ok)b.reset();return valid;}
Status validate_visit_appointment_cached_results(const CommonStore&c,const VisitAppointmentState*state,const VisitAuthoredCommandRead*commands){
 if(commands&&(&commands->common!=&c||!state||state->version!=2))return common_failure("VisitAppointmentDirectorCandidateMismatch",{},ErrorKind::internal);
 const bool selected=state&&state->version==2&&commands;
 if(!selected){for(const auto&h:c.state().history)if(h.kind=="offer_visit_appointment_authored")return common_failure("VisitAppointmentNpcOnlyCommand",h.result_id);for(const auto&row:c.state().results.rows())if(row.second&&row.second->kind=="offer_visit_appointment_authored")return common_failure("VisitAppointmentNpcOnlyCommand",row.first);}
 if(state){auto valid=bindings(c,*state);if(!valid.ok)return valid;}
 // Each actual authored source in the selected Director6 world has exactly one
 // immutable command adoption. The original claim/intent is validated separately.
 if(selected)for(const auto&row:state->offered.rows())if(row.second.authored_origin){auto valid=validate_visit_appointment_director_actor_effect(c,*state,*commands,row.second.contact.actor_id,{visit_appointment_module,visit_appointment_offered_kind,row.first});if(!valid.ok)return valid;}
 for(const auto&row:c.state().results.rows()){
  if(!row.second)continue;const auto&result=*row.second;const auto*effect=result.details?std::get_if<InteractionEffect>(&result.details->data):nullptr;
  const bool tagged=effect&&(effect->settlement_result.rfind(StableId{visit_appointment_offered_kind}+":",0)==0||effect->settlement_result.rfind(StableId{visit_appointment_collected_kind}+":",0)==0||effect->settlement_result.rfind(StableId{visit_appointment_accepted_kind}+":",0)==0);
  if(!command(result.kind)&&result.kind!="offer_visit_appointment_authored"&&!tagged)continue;
  if(!state||!result.ok||!result.details||!effect)return common_failure("VisitAppointmentCachedSourceRequired",row.first);
  const auto s=source(*state,effect->settlement_result);
  if(selected&&result.kind=="offer_visit_appointment_authored"){
   if(!(s.binding)||!s.authored||*s.binding)return common_failure("VisitAppointmentActualAuthoredSourceRequired",row.first);
   auto actual=read_visit_authored_command(*commands,{{visit_appointment_module,visit_appointment_offered_kind,effect->settlement_result},1},s.actor,result.kind,s.tick);if(!actual.ok)return {false,{},actual.error};
   if(actual.value.actual_result!=&result)return common_failure("VisitAppointmentAuthoredCacheMismatch",row.first);continue;
  }
  if(!s.binding||!*s.binding)return common_failure("VisitAppointmentPermanentResultRequired",row.first);const auto&b=**s.binding;
  if(row.first!=b.request_actor_id+":"+std::to_string(b.request_sequence)||result.result_id!=b.result_id||result.revision!=b.result_revision)return common_failure("VisitAppointmentCacheMismatch",row.first);
  auto valid=matches(*state,effect->settlement_result,b.request_actor_id,result.kind,result.tick,*result.details);if(!valid.ok)return valid;
 }
 for(const auto&h:c.state().history){
  if(selected&&h.kind=="offer_visit_appointment_authored"){std::size_t found=0;for(const auto&row:state->offered.rows())if(row.second.authored_origin){auto actual=read_visit_authored_command(*commands,{{visit_appointment_module,visit_appointment_offered_kind,row.first},1},row.second.contact.actor_id,h.kind,row.second.contact.tick);if(!actual.ok)return {false,{},actual.error};if(actual.value.command->result_id==h.result_id)++found;}if(found!=1)return common_failure("VisitAppointmentAuthoredHistorySourceRequired",h.result_id);continue;}
  if(command(h.kind)){if(!state)return common_failure("VisitAppointmentProfileRequired");std::size_t found=0;for(const auto&row:c.state().facts.rows()){const auto s=source(*state,row.first);if(s.binding&&*s.binding&&(**s.binding).result_id==h.result_id)++found;}if(found!=1)return common_failure("VisitAppointmentHistorySourceRequired",h.result_id);}
 }
 return common_success();
}
Status validate_visit_appointment_director_actor_effect(const CommonStore&c,const VisitAppointmentState&state,const VisitAuthoredCommandRead&commands,const StableId&actor,const SourceRef&ref){
 if(state.version!=2)return common_failure("VisitAppointmentDirectorPhysicalVersionRequired",ref.id,ErrorKind::unsupported_capability);
 if(&commands.common!=&c)return common_failure("VisitAppointmentDirectorCandidateMismatch",ref.id,ErrorKind::internal);
 const auto s=source(state,ref.id);if(ref.domain!=visit_appointment_module||ref.kind!=visit_appointment_offered_kind||!(s.binding)||!s.authored||*s.binding||s.actor!=actor)return common_failure("VisitAppointmentAuthoredEffectMismatch",ref.id);
 auto actual=read_visit_authored_command(commands,{ref,1},actor,"offer_visit_appointment_authored",s.tick);return actual.ok?common_success():Status{false,{},actual.error};
}
Outcome<MomentOwnerSource>read_visit_appointment_director_command_effect(const CommonStore&c,const VisitAppointmentState&before,const VisitAppointmentState&after,const StableId&actor,const ReceiptDetails&details,const WorldMoment&at){
 auto fail=[](const char*code)->Outcome<MomentOwnerSource>{return {false,{},common_failure(code).error};};
 if(before.version!=2||after.version!=2)return fail("VisitAppointmentDirectorPhysicalVersionRequired");
 std::vector<StableId>added;
 if(!additions(before,after,before.offered,after.offered,added)||!additions(before,after,before.collected,after.collected,added)||!additions(before,after,before.accepted,after.accepted,added)||added.size()!=1)return fail("VisitAppointmentActualAuthoredDeltaRequired");
 const auto&id=added.front();const auto s=source(after,id);const auto*h=c.state().facts.find(id);const auto*effect=std::get_if<InteractionEffect>(&details.data);
 if(!(s.binding)||!s.authored||*s.binding||s.kind!=visit_appointment_offered_kind||s.actor!=actor||s.tick!=at.half_day_tick||!h||h->id!=id||h->domain!=visit_appointment_module||h->kind!=visit_appointment_offered_kind||!effect||effect->settlement_result!=id||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return fail("VisitAppointmentActualAuthoredSourceRequired");
 return {true,{{visit_appointment_module,visit_appointment_offered_kind,id},1},{}};
}
}
